def can_partition_k_subsets(nums, k):
    s = sum(nums)
    if s % k: return False
    t = s // k; n = len(nums); dp = [-1] * (1 << n); dp[0] = 0
    for m in range(1 << n):
        if dp[m] < 0: continue
        for i in range(n):
            if not m >> i & 1 and dp[m] + nums[i] <= t:
                dp[m | 1 << i] = (dp[m] + nums[i]) % t
    return dp[-1] == 0

