bool canPartitionKSubsets(vector<int>& a, int k) {
    int s = accumulate(a.begin(), a.end(), 0); if (s % k) return false; int t = s / k, n = a.size();
    vector<int> dp(1 << n, -1); dp[0] = 0;
    for (int m = 0; m < (1 << n); m++) { if (dp[m] < 0) continue; for (int i = 0; i < n; i++) if (!(m >> i & 1) && dp[m] + a[i] <= t) dp[m | 1 << i] = (dp[m] + a[i]) % t; }
    return dp[(1 << n) - 1] == 0;
}
